		// in place, using the symmetry of the update formula.
		//
		// Original update (for a given k):
		//   for (i = 0; i < k; i++)
		//     z[i] = y[i] + alpha * y[k - i - 1];
		//   for (i = 0; i < k; i++)
		//     y[i] = z[i];
		//
		// Let j = k - i - 1. For each pair (i, j) with i < j:
		//   y_new[i] = y_old[i] + alpha * y_old[j];
		//   y_new[j] = y_old[j] + alpha * y_old[i];
