							auto i = noarr::get_index<'i'>(i_state);
							auto j = k - i - 1U;
							auto j_state = noarr::idx<'i'>(j);

							// Cache old values before overwriting
							num_t yi = y[i_state];
							num_t yj = y[j_state];

							// Symmetric in-place update
							num_t new_yi = yi + alpha * yj;
							num_t new_yj = yj + alpha * yi;

							y[i_state] = new_yi;
							y[j_state] = new_yj;
						});
