	using namespace noarr;

	// length of the 1D vectors
	auto n = r | get_length<'i'>();

	// pseudo-structure for the k loop (k in [0, n-1])
	auto k_structure = noarr::scalar<char>() ^ noarr::vector<'k'>(n);

	// pseudo-structure for pair indices p used in the in-place update of y
	// p will run over [0, num_pairs) where num_pairs <= k/2 <= n/2 <= n
	auto pair_structure = noarr::scalar<char>() ^ noarr::vector<'p'>(n);

	num_t alpha;
	num_t beta;
	num_t sum;

	#pragma scop
	// y[0] = -r[0];
	y[noarr::idx<'i'>(0)] = -r[noarr::idx<'i'>(0)];
	beta = SCALAR_VAL(1.0);
	alpha = -r[noarr::idx<'i'>(0)];

	// Traverse k = 1 .. n-1 using a Noarr traverser over k_structure.
	// We restrict the range with slice<'k'>(1, n-1).
