			//   yi = y[i]; yj = y[j];
			//   y[i] = yi + alpha * yj;
			//   y[j] = yj + alpha * yi;
			//
			// For the middle element when k is odd (i == j), we have:
			//   y[c] = y[c] + alpha * y[c];
