namespace {

// basic 1D proto-structure over dimension 'i'
constexpr auto i_vec = noarr::vector<'i'>();

struct tuning {
	// 1D layout over dimension 'i'
	// (kept simple and contiguous; for this 1D problem this already gives
	//  optimal spatial locality for all three vectors r, y, z)
	DEFINE_PROTO_STRUCT(r_layout, i_vec);
	DEFINE_PROTO_STRUCT(y_layout, i_vec);
} tuning;

// initialization function: r[i] = n + 1 - i
void init_array(auto r) {
	using namespace noarr;

	auto n = r | get_length<'i'>();

	// Simple contiguous traversal over 'i'
	traverser(r).for_each([=](auto state) {
		auto i = get_index<'i'>(state);
		r[state] = static_cast<num_t>(n + 1 - i);
	});
}

// computation kernel
// - kept noinline as in the original benchmark
// - flatten encourages the compiler to inline the traversal machinery
[[gnu::flatten, gnu::noinline]]
void kernel_durbin(auto r, auto y) {
	using namespace noarr;

	// length of the 1D vectors
	auto n = r | get_length<'i'>();

	// local temporary z[0..n-1]
	// contiguous 1D layout, same as r and y
	auto z = noarr::bag(noarr::scalar<num_t>() ^ noarr::vector<'i'>(n));

	// pseudo-structure for the k loop (k = 0 .. n-1)
	auto k_structure = noarr::scalar<char>() ^ noarr::vector<'k'>(n);

	// Pre-build base traversers once and reuse them inside the k-loop.
	// This avoids repeatedly constructing traversers for r/y/z on every k
	// iteration while still expressing all loops via Noarr traversers.
	auto k_trav_base  = traverser(k_structure);
	auto yr_trav_base = traverser(y, r);
	auto yz_trav_base = traverser(y, z);

	// Frequently used index state for i = 0
	const auto i0 = idx<'i'>(0);

	num_t alpha;
	num_t beta;
	num_t sum;

	#pragma scop
	// y[0] = -r[0];
	y[i0] = -r[i0];
	beta = SCALAR_VAL(1.0);
	alpha = -r[i0];

	// for (k = 1; k < n; k++)
	// We iterate k over [1, n-1] using a 1D traverser over 'k'
	k_trav_base
		.order(slice<'k'>(1, n - 1)) // slice gives k in {1, ..., n-1}
		.template for_dims<'k'>([&](auto k_trav) {
			// Extract the current k from the traverser's fixed state
			auto k_state = k_trav.state();
			auto k = get_index<'k'>(k_state);
			auto k_minus_one = k - 1; // used in i-dependent reverse accesses

			// beta = (1 - alpha * alpha) * beta;
			beta = (SCALAR_VAL(1.0) - alpha * alpha) * beta;

			// sum = 0.0;
			sum = SCALAR_VAL(0.0);

			// -----------------------------------------------------------------
			// sum = Σ_{i=0}^{k-1} r[k - i - 1] * y[i]
			// Implemented as a contiguous traversal over i in [0, k-1].
			// We reuse yr_trav_base and only add a slice for this k.
			// -----------------------------------------------------------------
			yr_trav_base
				.order(slice<'i'>(0, k)) // i in {0, ..., k-1}
				.for_each([&](auto ir_state) {
					auto i = get_index<'i'>(ir_state);

					// Access r[k - i - 1] via a separate state on dim 'i'
					auto r_state = idx<'i'>(k_minus_one - i);

					sum += r[r_state] * y[ir_state];
				});

			// alpha = - (r[k] + sum) / beta;
			alpha = -(r[idx<'i'>(k)] + sum) / beta;

			// -----------------------------------------------------------------
			// z[i] = y[i] + alpha * y[k - i - 1]  for i = 0 .. k-1
			//
			// This must be done into a temporary (z), because the right-hand
			// side uses "old" y values which would be destroyed by an
			// in-place update. We preserve the original PolyBench semantics.
			// -----------------------------------------------------------------
			yz_trav_base
				.order(slice<'i'>(0, k)) // i in {0, ..., k-1}
				.for_each([&](auto iz_state) {
					auto i = get_index<'i'>(iz_state);

					auto y_rev_state = idx<'i'>(k_minus_one - i);

					z[iz_state] = y[iz_state] + alpha * y[y_rev_state];
				});

			// -----------------------------------------------------------------
			// y[i] = z[i]  for i = 0 .. k-1
			//
			// Copy the newly computed coefficients from z back into y.
			// Contiguous traversal over the same slice; this copy is cheap
			// and keeps the algorithm straightforward and numerically stable.
			// -----------------------------------------------------------------
			yz_trav_base
				.order(slice<'i'>(0, k))
				.for_each([&](auto iz_state) {
					y[iz_state] = z[iz_state];
				});

			// y[k] = alpha;
			y[idx<'i'>(k)] = alpha;
		});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// input data
	auto set_lengths = noarr::set_length<'i'>(n);

	auto r = noarr::bag(noarr::scalar<num_t>() ^ tuning.r_layout ^ set_lengths);
	auto y = noarr::bag(noarr::scalar<num_t>() ^ tuning.y_layout ^ set_lengths);

