			//   sum = sum_{i=0}^{k-1} r[k - i - 1] * y[i];
			//
			// We keep this in its straightforward form for clarity and
			// predictable memory access (sequential in y, mostly cache‑
			// friendly in r).
			// --------------------------------------------------------
			noarr::traverser(y, r)
				.order(noarr::slice<'i'>(0, k)) // i in [0, k)
				.for_each([&](auto ir_state) {
					auto i = noarr::get_index<'i'>(ir_state);

					auto r_state = noarr::idx<'i'>(k - i - 1);
					sum += r[r_state] * y[ir_state];
				});

			// alpha = - (r[k] + sum) / beta;
			alpha = -(r[noarr::idx<'i'>(k)] + sum) / beta;

			// --------------------------------------------------------
			// y update:
			//
			// Original algorithm (three passes):
			//
			//   for (i = 0; i <  k; i++) z[i] = y[i] + alpha * y[k-i-1];
			//   for (i = 0; i <  k; i++) y[i] = z[i];
			//   y[k] = alpha;
			//
			// This uses an auxiliary array z[0..n-1] to avoid overwriting
			// values of y that are still needed.
			//
			// Optimized variant (default here, controlled by
			// tuning::use_inplace_pairwise_y_update):
			//
			//   We observe that updates come in symmetric pairs:
			//     y_new[i] = y_old[i] + alpha * y_old[k-i-1]
			//     y_new[j] = y_old[j] + alpha * y_old[i], where j = k-i-1
			//
			//   For each i < j we can update (i, j) in-place using two
			//   temporaries (y_old[i], y_old[j]). For odd k there is
			//   one center index c = (k-1)/2 with:
			//     y_new[c] = (1 + alpha) * y_old[c]
			//
			//   This removes the temporary z, halves the number of
			//   traversals over y (2 instead of 3), and improves cache
			//   locality by operating directly in-place.
			// --------------------------------------------------------
			if constexpr (tuning::use_inplace_pairwise_y_update) {
				// Number of (i, k-i-1) pairs with i < k-i-1.
				auto half_k = k / 2; // floor(k/2)

				// Handle all symmetric pairs (i, j) with i < j.
				noarr::traverser(y)
					.order(noarr::slice<'i'>(0, half_k)) // i in [0, half_k)
					.for_each([&](auto i_state) {
						auto i = noarr::get_index<'i'>(i_state);
						auto j = k - i - 1; // partner index

						auto j_state = noarr::idx<'i'>(j);

						// Cache old values before overwriting.
						num_t yi = y[i_state];
						num_t yj = y[j_state];

						// In-place symmetric update:
						//   y[i] = y_old[i] + alpha * y_old[j]
						//   y[j] = y_old[j] + alpha * y_old[i]
						y[i_state] = yi + alpha * yj;
						y[j_state] = yj + alpha * yi;
					});

				// If k is odd, there is one center index that maps to itself:
				//   c = (k-1)/2,  j = k-c-1 = c
				// For this index:
				//   y_new[c] = y_old[c] + alpha * y_old[c]
				//            = (1 + alpha) * y_old[c]
				if (k & 1u) {
					auto c = k / 2; // (k-1)/2 for odd k
					auto c_state = noarr::idx<'i'>(c);
					y[c_state] = (SCALAR_VAL(1.0) + alpha) * y[c_state];
				}
			} else {
				// Fallback: original three-pass formulation using
				// an auxiliary z[0..n-1] stored in a Noarr bag.
				// This branch is never instantiated when the
				// tuning flag is true, but it provides a simple,
				// easily verifiable reference implementation and
				// a tuning knob for experimentation.

				// local temporary z[0..n-1]
				auto z = noarr::bag(noarr::scalar<num_t>() ^ noarr::vector<'i'>(n));

				// for (i = 0; i < k; i++) z[i] = y[i] + alpha * y[k - i - 1];
				noarr::traverser(y, z)
					.order(noarr::slice<'i'>(0, k))
					.for_each([&](auto iz_state) {
						auto i = noarr::get_index<'i'>(iz_state);

						auto y_rev_state = noarr::idx<'i'>(k - i - 1);
						z[iz_state] = y[iz_state] + alpha * y[y_rev_state];
					});

				// for (i = 0; i < k; i++) y[i] = z[i];
				noarr::traverser(y, z)
					.order(noarr::slice<'i'>(0, k))
					.for_each([&](auto iz_state) {
						y[iz_state] = z[iz_state];
					});
			}

			// y[k] = alpha;
			y[noarr::idx<'i'>(k)] = alpha;
		});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// input data
	auto set_lengths = noarr::set_length<'i'>(n);

	auto r = noarr::bag(noarr::scalar<num_t>() ^ tuning.r_layout ^ set_lengths);
	auto y = noarr::bag(noarr::scalar<num_t>() ^ tuning.y_layout ^ set_lengths);

	// initialize data
	init_array(r.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_durbin(r.get_ref(), y.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (also prevents dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, y.get_ref());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
