// initialization function: r[i] = n + 1 - i
void init_array(auto r) {
	using namespace noarr;

	auto n = r | get_length<'i'>();

	traverser(r).for_each([=](auto state) {
		auto i = get_index<'i'>(state);
		r[state] = (num_t)(n + 1 - i);
	});
}

// computation kernel
// NOTE: The main semantic change vs. the baseline is that the update
// y[i] = y[i] + alpha * y[k-i-1] is performed in-place using pairwise
// symmetric updates instead of going through a temporary z[ ] array.
// This preserves the mathematical result while cutting memory traffic
// (no second buffer and no extra copy loop) and improving locality.
[[gnu::flatten, gnu::noinline]]
void kernel_durbin(auto r, auto y) {
	using namespace noarr;

	// length of the 1D vectors
	auto n = r | get_length<'i'>();

	// pseudo-structure for the k loop
	auto k_structure = noarr::scalar<char>() ^ noarr::vector<'k'>(n);

	num_t alpha;
	num_t beta;
	num_t sum;

	#pragma scop
	// y[0] = -r[0];
	const auto i0_state = noarr::idx<'i'>(0);
	const num_t r0 = r[i0_state];
	y[i0_state] = -r0;
	beta = SCALAR_VAL(1.0);
	alpha = -r0;

	// for (k = 1; k < n; k++)
	noarr::traverser(k_structure)
		.order(noarr::slice<'k'>(1, n - 1))
		.template for_dims<'k'>([&](auto k_trav) {
			auto k_state = k_trav.state();
			auto k = noarr::get_index<'k'>(k_state);

			// beta = (1 - alpha * alpha) * beta;
			beta = (SCALAR_VAL(1.0) - alpha * alpha) * beta;

			// sum = 0.0;
			sum = SCALAR_VAL(0.0);

			// for (i = 0; i < k; i++) sum += r[k - i - 1] * y[i];
			noarr::traverser(y, r)
				.order(noarr::slice<'i'>(0, k))
				.for_each([&](auto ir_state) {
					auto i = noarr::get_index<'i'>(ir_state);
					auto r_state = noarr::idx<'i'>(k - i - 1);

					sum += r[r_state] * y[ir_state];
				});

			// alpha = - (r[k] + sum) / beta;
			alpha = -(r[noarr::idx<'i'>(k)] + sum) / beta;

			// Optimized in-place update of y:
			//
			// Original code:
			//   for (i = 0; i < k; i++) z[i] = y[i] + alpha * y[k - i - 1];
			//   for (i = 0; i < k; i++) y[i] = z[i];
			//
			// For each i:
			//   new_y[i] = old_y[i] + alpha * old_y[k - i - 1]
			//
			// We can pair indices (i, j = k-1-i). For i < j:
			//   new_y[i] = old_y[i] + alpha * old_y[j]
			//   new_y[j] = old_y[j] + alpha * old_y[i]
			//
			// For the middle element when k is odd (i == j):
			//   new_y[c] = old_y[c] + alpha * old_y[c] = (1+alpha)*old_y[c]
			//
			// Doing the update pairwise with temporaries guarantees we
			// only use original values on the right-hand side, so the
			// result is identical to the two-loop z[ ] formulation,
			// but we avoid the temporary buffer and one whole pass.

			const std::size_t half_k = k / 2; // number of (i,j) pairs with i < j

			// Handle all pairs (i, j=k-1-i) where i < j
			noarr::traverser(y)
				.order(noarr::slice<'i'>(0, half_k))
				.for_each([&](auto i_state) {
					auto i = noarr::get_index<'i'>(i_state);
					auto j = k - 1 - i;
					auto j_state = noarr::idx<'i'>(j);

					// Load original pair values once
					const num_t yi = y[i_state];
					const num_t yj = y[j_state];

					// Symmetric in-place update
					y[i_state] = yi + alpha * yj;
					y[j_state] = yj + alpha * yi;
				});

			// If k is odd, there is a middle element c = (k-1)/2
			// which maps to itself. We update it once with:
			//   new_y[c] = old_y[c] + alpha * old_y[c]
			if (k & 1u) {
				const std::size_t c = k / 2;
				auto c_state = noarr::idx<'i'>(c);
				const num_t yc = y[c_state];
				y[c_state] = yc + alpha * yc;
			}

			// y[k] = alpha;
			y[noarr::idx<'i'>(k)] = alpha;
		});
	#pragma endscop
}

